function G.attack(clips,id)return G.isBaton(id)and G.swing or clips.punch end
function G.socket(name,position)
 local frames=sockets[name]or sockets.idle;local i=math.max(0,math.min(#frames-1,position));local k=math.floor(i)+1;local t=i-math.floor(i);local a,b=frames[k],frames[math.min(k+1,#frames)];local result={}
 for n=1,12 do result[n]=a[n]+(b[n]-a[n])*t end
 -- A fixed palm-local grip follows wrist rotation; no world-axis clamping or roll flips.
 local weight=(name=='idle'or name=='walk'or name=='run')and 1 or 0

 if weight>0 then
  local rotation={{0.16211482,0.97741652,-0.13555698},{-0.74982077,0.21132167,0.62698644},{0.64147311,0.0,0.7671456}};local old={};for i=4,12 do old[i]=result[i]end
  for axis=1,3 do for k=1,3 do
   local value=0;for j=1,3 do value=value+old[3+(j-1)*3+k]*rotation[axis][j]end
   local n=3+(axis-1)*3+k;result[n]=old[n]+(value-old[n])*weight
  end end
 end
 -- Orthonormalize the interpolated socket so the weapon never stretches in a blend.
 local function norm(v)local n=math.sqrt(v[1]^2+v[2]^2+v[3]^2);return{v[1]/n,v[2]/n,v[3]/n}end
 local a=norm({result[4],result[5],result[6]});local b={result[7],result[8],result[9]};local dot=a[1]*b[1]+a[2]*b[2]+a[3]*b[3]
 for k=1,3 do b[k]=b[k]-dot*a[k]end;b=norm(b)
 local c={a[2]*b[3]-a[3]*b[2],a[3]*b[1]-a[1]*b[3],a[1]*b[2]-a[2]*b[1]}
 local sign=c[1]*result[10]+c[2]*result[11]+c[3]*result[12]<0 and -1 or 1
 for k=1,3 do result[3+k]=a[k];result[6+k]=b[k];result[9+k]=c[k]*sign end
 return result
end

-- Blend only combat stance changes; walking/running cadence is untouched.
local previousName,lastPose,lastSocket,fromPose,fromSocket,elapsed,alpha
lastPose={};elapsed=1;alpha=1
function G.preparePose(name,dt)
 if name~=previousName then
  if previousName and(name=='ready'or previousName=='ready'or previousName=='swing'or name=='run'or previousName=='run'or name=='walk'or previousName=='walk')then
   fromPose=lastPose;fromSocket=lastSocket;elapsed=0
  else fromPose=nil;fromSocket=nil;elapsed=1 end
 end
 previousName=name;elapsed=elapsed+dt;alpha=math.min(1,elapsed/.18);lastPose={}
 if alpha>=1 then fromPose=nil;fromSocket=nil end
end
function G.blendVertex(i,x,y,z)
 local a=fromPose and fromPose[i]
 if a then x=a[1]+(x-a[1])*alpha;y=a[2]+(y-a[2])*alpha;z=a[3]+(z-a[3])*alpha end
 lastPose[i]={x,y,z};return x,y,z
end
function G.blendSocket(socket)
 local r={};for i=1,12 do r[i]=fromSocket and(fromSocket[i]+(socket[i]-fromSocket[i])*alpha)or socket[i]end
 -- Gram-Schmidt keeps the crowbar rigid throughout the lowering animation.
 local function norm(v)local n=math.sqrt(v[1]^2+v[2]^2+v[3]^2);return{v[1]/n,v[2]/n,v[3]/n}end
 local x=norm({r[4],r[5],r[6]});local y={r[7],r[8],r[9]};local dot=x[1]*y[1]+x[2]*y[2]+x[3]*y[3]
 for k=1,3 do y[k]=y[k]-dot*x[k]end;y=norm(y)
 local z={x[2]*y[3]-x[3]*y[2],x[3]*y[1]-x[1]*y[3],x[1]*y[2]-x[2]*y[1]};local sign=z[1]*r[10]+z[2]*r[11]+z[3]*r[12]<0 and -1 or 1
 for k=1,3 do r[k+3]=x[k];r[k+6]=y[k];r[k+9]=z[k]*sign end
 lastSocket=r;return r
end
return G
